text:
input::-moz-search-clear-button {
  inline-size: 28px;
  block-size: 28px;
  margin-block: auto;
  padding: 0;
  background-image: var(--icon-close);
  background-size: 16px;
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
}
